const glimDefaultMotion = GlimMotion.subtle;

/// How the glyphs are drawn, as `GlyphStyle` in the core.
enum GlimGlyphStyle { filled, line }

const glimDefaultGlyphs = GlimGlyphStyle.filled;

/// The house type: the face this package ships, the fallbacks an app ships
/// for the scripts it does not draw, three weights and a tracking per size.
abstract final class GlimType {
  static const family = 'IBM Plex Sans';
  static const fallback = <String>['Noto Sans', 'Noto Sans Arabic', 'Noto Sans Hebrew', 'Noto Sans Thai', 'Noto Sans CJK SC', 'Noto Sans SC'];

  static const regular = FontWeight.w400;
  static const medium = FontWeight.w500;
  static const strong = FontWeight.w600;

  /// The tracking of each size, in ems.
  static const trackingStatus = -0.012;
  static const trackingTitle = -0.01;
  static const trackingBody = -0.006;
  static const trackingSubline = -0.003;
  static const trackingMeta = 0.01;
}

/// The width of the focus ring.
const double glimFocusRingWidth = 2;

/// The corner a well or a sub-card takes inside a card, so the two curves run
/// side by side.
extension GlimShapeNesting on GlimShape {
  double get nested => card > 6 ? card - 6 : 0;
}
